// Writes the golden R0 compatibility fixtures into tests/fixtures/r0/.
//
// Run ONCE with the R0 code (it was run at the R0 release). The files are
// committed and must never be regenerated by later versions: their whole
// point is to be real data written by the old code, so tests can prove that
// every later version still reads it.
//
//   node tools/fixtures/make-r0.mjs
import { writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { IDBFactory } from 'fake-indexeddb';
import { Store } from '../../src/data/store.js';
import { createBackup } from '../../src/data/backup.js';
import { V1_LOCAL_KEY } from '../../src/data/migrate-v1.js';
import { APP_VERSION, DATA_SCHEMA } from '../../src/version.js';

const out = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'tests', 'fixtures', 'r0');
mkdirSync(out, { recursive: true });

const DAY = 86400000;
const T0 = Date.UTC(2026, 9, 1, 16, 0, 0); // 1 Oct 2026, the v1 era

// A realistic v1 save: every record shape v1 could have written.
const v1Save = {
  v: 1,
  name: 'Freddie',
  coins: 412,
  xp: 1380,
  owned: ['shirt-blue', 'hat-none', 'trail-none', 'hat-cap', 'shirt-red', 'trail-sparks'],
  look: { shirt: 'shirt-red', hat: 'hat-cap', trail: 'trail-sparks' },
  learn: {
    skills: {
      // mastered (fast-tracked: 4/4 then more practice)
      'm.bonds10': { n: 18, c: 17, ema: 0.93, streak: 6, box: 4, due: T0 + 7 * DAY, last: T0, ms: 2100 },
      'm.x2': { n: 22, c: 21, ema: 0.95, streak: 9, box: 5, due: T0 + 21 * DAY, last: T0 - DAY, ms: 1900 },
      'm.x10': { n: 4, c: 4, ema: 0.9, streak: 4, box: 3, due: T0 + 3 * DAY, last: T0 - 2 * DAY, ms: 2600 },
      // practising
      'm.x5': { n: 9, c: 6, ema: 0.71, streak: 1, box: 1, due: T0 + 10 * 60000, last: T0, ms: 3400 },
      'v.alphaNext': { n: 12, c: 10, ema: 0.82, streak: 3, box: 2, due: T0 + DAY, last: T0, ms: 2800 },
      // introduced, mostly wrong
      'v.alphaJump': { n: 3, c: 1, ema: 0.45, streak: 0, box: 0, due: T0, last: T0, ms: 5200 },
      's.count1': { n: 7, c: 7, ema: 0.94, streak: 7, box: 4, due: T0 + 7 * DAY, last: T0 - 3 * DAY, ms: 4100 },
      's.rotY': { n: 5, c: 3, ema: 0.66, streak: 2, box: 1, due: T0, last: T0 - DAY, ms: 6100 },
      // partial record (no ema) and an id no version ever had
      'm.add20': { n: 5, c: 5 },
      'm.bond10': { n: 14, c: 12 },
    },
    recent: { maths: [1, 1, 0, 1, 1, 1, 1, 0, 1, 1], verbal: [1, 0, 1, 1, 1], spatial: [1, 1, 0, 1] },
  },
  best: { obby: 61240, vault: 88410, lab: 0 },
  day: { date: '2026-10-01', ms: 1260000, answered: 64, correct: 55, bonusMin: 0, stars: { obby: true, vault: true, lab: false }, chest: false },
  history: [
    { date: '2026-09-28', ms: 900000, answered: 50, correct: 41 },
    { date: '2026-09-29', ms: 1500000, answered: 77, correct: 66 },
    { date: '2026-09-30', ms: 600000, answered: 31, correct: 25 },
  ],
  totals: { ms: 4260000, answered: 222, correct: 187, runs: 19 },
  settings: { readAloud: true, dailyMin: 30, pin: '2468' },
  created: T0 - 10 * DAY,
};

// A second v1 save, exported as a v1 backup code from another iPad.
const v1Other = {
  v: 1,
  name: 'Freddie',
  coins: 95,
  xp: 260,
  owned: ['shirt-blue', 'hat-none', 'trail-none', 'hat-crown'],
  look: { shirt: 'shirt-blue', hat: 'hat-crown', trail: 'trail-none' },
  learn: {
    skills: {
      'm.x2': { n: 8, c: 8, ema: 0.9, streak: 8, box: 3, due: T0 + 3 * DAY, last: T0 - 5 * DAY, ms: 2500 },
      'v.code1': { n: 10, c: 9, ema: 0.88, streak: 5, box: 3, due: T0 + 3 * DAY, last: T0 - 4 * DAY, ms: 7000 },
    },
    recent: { maths: [1, 1, 1], verbal: [1, 1] },
  },
  best: { obby: 70000, vault: 0, lab: 54000 },
  totals: { ms: 1200000, answered: 60, correct: 54, runs: 6 },
  history: [{ date: '2026-09-27', ms: 1200000, answered: 60, correct: 54 }],
  settings: { readAloud: false, dailyMin: 25, pin: '1357' },
  created: T0 - 12 * DAY,
};
const v1Code = btoa(unescape(encodeURIComponent(JSON.stringify(v1Other))));

class MemStorage {
  constructor() {
    this.m = new Map();
  }
  getItem(k) {
    return this.m.has(k) ? this.m.get(k) : null;
  }
  setItem(k, v) {
    this.m.set(k, String(v));
  }
  removeItem(k) {
    this.m.delete(k);
  }
}

// An R0 iPad: migrated the v1 save on first launch, then played a run.
const idb = new IDBFactory();
const storage = new MemStorage();
storage.setItem(V1_LOCAL_KEY, JSON.stringify(v1Save));
const store = await Store.open({ idb, storage });
store.data.coins += 37;
store.data.xp += 90;
store.data.totals.runs += 1;
const attempts = [
  { s: 'm.x5', c: 1, f: 1, ms: 2900, coins: 5 },
  { s: 'm.x5', c: 0, f: 1, ms: 5100, coins: 0 },
  { s: 'm.x5', c: 1, f: 0, ms: 3300, coins: 1 },
  { s: 'm.x3', c: 1, f: 1, ms: 4100, coins: 5 },
];
for (const a of attempts) store.recordAttempt({ ...a, fp: 'r0fp' + a.s });
await store.endRun('obby', { done: true, right: 7, total: 8, timeMs: 71000, bonus: 64, star: false });
await store.write();

const dump = {
  meta: (await store.db.getAll('meta')).filter((m) => m.k !== 'pin'),
  state: await store.db.get('state', 'game'),
  ops: await store.getOps(),
};
const plain = await createBackup(store);
const locked = await createBackup(store, { passphrase: 'pine cones' });

writeFileSync(join(out, 'v1-save.json'), JSON.stringify(v1Save, null, 2));
writeFileSync(join(out, 'v1-code.txt'), v1Code);
writeFileSync(join(out, 'r0-idb.json'), JSON.stringify(dump, null, 2));
writeFileSync(join(out, 'r0-plain.bloxbak'), plain.bytes);
writeFileSync(join(out, 'r0-pass.bloxbak'), locked.bytes);
writeFileSync(
  join(out, 'manifest.json'),
  JSON.stringify(
    {
      madeBy: { app: APP_VERSION, schema: DATA_SCHEMA },
      passphrase: 'pine cones',
      v1Save: { coins: 412, xp: 1380, skills: Object.keys(v1Save.learn.skills).length, pin: '2468' },
      v1Code: { coins: 95, xp: 260, skills: 2 },
      r0: {
        coins: store.data.coins,
        xp: store.data.xp,
        name: store.data.name,
        owned: store.data.owned.length,
        skills: Object.keys(store.data.learn.skills).length,
        ops: dump.ops.length,
        profile: store.profileId,
        device: store.deviceId,
        answered: store.data.totals.answered,
      },
    },
    null,
    2,
  ),
);
console.log(`Wrote R0 fixtures to ${out}: ${dump.ops.length} ops, ${store.data.coins} coins.`);
